import{_ as t,o,c as a,ag as r}from"./chunks/framework.2cFhd8Ux.js";const f=JSON.parse('{"title":"Week 16 — Final Defense","description":"","frontmatter":{"source":"weeks/16-final-defense/README.md"},"headers":[],"relativePath":"weeks/16-final-defense/index.md","filePath":"weeks/16-final-defense/index.md"}'),n={name:"weeks/16-final-defense/index.md"};function s(i,e,d,l,h,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="week-16--final-defense" tabindex="-1">Week 16 — Final Defense <a class="header-anchor" href="#week-16--final-defense" aria-label="Permalink to &quot;Week 16 — Final Defense&quot;">​</a></h1><blockquote><p>Finals week: your team shows its contribution working, reruns a check in front of the room and names a limitation, and then each of you explains your own work with the AI off.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before the Seminar</strong></td><td>No Seminar in finals week. Before the slot: push the <code>final</code> tag, open a Codespace on it 30 minutes ahead, reread your PRs and <code>AI_LOG.md</code> entries (<a href="#before-the-slot">checklist</a>)</td></tr><tr><td><strong>Seminar</strong></td><td>None. The <strong>final defense</strong> runs in the course&#39;s scheduled <strong>2-hour final exam slot</strong> (Regulation H-1-b: final sessions follow the approved final exam schedule): [day, time and room, on Canvas]</td></tr><tr><td><strong>Lab</strong></td><td>None. The <a href="#lab">final deliverables</a> are due this week</td></tr><tr><td><strong>Due before next week&#39;s Seminar</strong></td><td>There&#39;s no next week. The <code>final</code> tag is due <strong>before the start of the slot</strong>; the final report, peer evaluation 3 and the CS [5xxx] final paper by <strong>11:59 pm on the last day of finals week</strong></td></tr><tr><td><strong>AI use this week</strong></td><td>🔴 AI off for the individual questions and peer evaluation 3. The demo shows work built under the course&#39;s rules. 🟡 AI limited for the final report (the limitations, contributions and reflection sections are the team&#39;s own)</td></tr><tr><td><strong>Reading</strong></td><td>None</td></tr><tr><td><strong>Reading response</strong></td><td>None (they run in weeks 1–15)</td></tr><tr><td><strong>Team project</strong></td><td>The Final: 65 points, the report and repository (35), the demo (10) and your individual questions (20) (<a href="./../../project/milestones.html#final">milestones</a>)</td></tr><tr><td><strong>Graduate track</strong></td><td>Defend with your team; the final paper on Canvas (<a href="./../../graduate/empirical-study.html#the-paper">the paper</a>)</td></tr><tr><td><strong>Time</strong></td><td>The 2-hour slot, plus finishing the report (and, for CS [5xxx], the paper)</td></tr></tbody></table><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>At the final defense you show that you can:</p><ol><li><strong>Demonstrate</strong> a contribution to a real codebase working on a tagged snapshot.</li><li><strong>Reproduce</strong> your own evidence: rerun a check live and reconcile it with your report.</li><li><strong>Explain and defend</strong> your code and decisions without AI: what you specified, delegated and verified, and why.</li><li><strong>Predict</strong> what a change would break, and how you&#39;d find out.</li><li><strong>Account honestly</strong> for your AI use and your contribution&#39;s limits, consistent with the record.</li></ol><h2 id="seminar" tabindex="-1">Seminar <a class="header-anchor" href="#seminar" aria-label="Permalink to &quot;Seminar&quot;">​</a></h2><p>There is no Seminar this week. The final defense takes its place, in the final exam slot. The full guide, with the rubric, is <a href="./../../project/final-defense.html">The Final Defense</a>.</p><h3 id="before-the-slot" tabindex="-1">Before the slot <a class="header-anchor" href="#before-the-slot" aria-label="Permalink to &quot;Before the slot&quot;">​</a></h3><ul><li>☐ <strong>Push the <code>final</code> tag</strong> on your team fork. Staff record the commit it points to at the start of the slot; that&#39;s what you demo and what&#39;s graded (<a href="./../../project/milestones.html#the-repository-snapshot">the repository snapshot</a>).</li><li>☐ <strong>Open a Codespace on the tag 30 minutes early,</strong> already built, with your check&#39;s command ready. Free machines can be slow to start.</li><li>☐ <strong>Bring your demo script</strong> from week 15, with a fallback for every step.</li><li>☐ <strong>Each member:</strong> reread your own PRs, your <code>course/AI_LOG.md</code> entries and the week 14 draft. Your individual questions come from them.</li><li>☐ <strong>Close AI tools</strong> before you arrive: completions off, chat panels closed.</li><li>☐ <strong>Accommodations</strong> agreed with the instructor in advance (<a href="./../../project/final-defense.html#accommodations">options</a>).</li></ul><h3 id="in-the-slot" tabindex="-1">In the slot <a class="header-anchor" href="#in-the-slot" aria-label="Permalink to &quot;In the slot&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Time</th><th>What</th></tr></thead><tbody><tr><td>5 min</td><td>Opening: the order of teams, the rules, AI tools closed</td></tr><tr><td>About 18 min per team</td><td>Setup (1) · <strong>demo</strong> (6) · <strong>team question</strong> (1–2) · <strong>individual questions</strong>, about 2–3 minutes per member · changeover (1)</td></tr><tr><td>5 min</td><td>Close</td></tr></tbody></table><p>Everyone stays for the whole slot.</p><p><strong>The demo (6 minutes):</strong> what you contributed and why; the contribution working on the <code>final</code> tag, on the main scenario and one edge case; one <strong>check rerun live</strong> and compared with your report; and <strong>one honest limitation</strong>, stated without being asked. <strong>The team question</strong> is usually about a decision in your report; any member may answer.</p><p><strong>Your individual questions</strong> (🔴 AI off) come from four kinds: explain your contribution, defend a decision, predict or modify, and account for AI use and limits. You may use the tagged repository on screen, and you may ask in advance to take them privately at the end of the slot.</p><h2 id="lab" tabindex="-1">Lab <a class="header-anchor" href="#lab" aria-label="Permalink to &quot;Lab&quot;">​</a></h2><p>There is no Lab this week. These are the course&#39;s last deliverables (<a href="./../../project/milestones.html#final">full list</a>):</p><table tabindex="0"><thead><tr><th>Deliverable</th><th>Who</th><th>Where</th><th>Due</th></tr></thead><tbody><tr><td><strong>The repository snapshot:</strong> the <code>final</code> tag</td><td>Team</td><td>Team fork</td><td>Before the start of the final exam slot</td></tr><tr><td><strong>The final defense</strong></td><td>Every member</td><td>The final exam slot</td><td>The slot</td></tr><tr><td><strong>The final report</strong> (nine sections, about 2,000–3,500 words)</td><td>Team</td><td>Canvas</td><td>11:59 pm on the last day of finals week</td></tr><tr><td><strong>Peer evaluation 3</strong> (🔴 AI off)</td><td>Each member</td><td>Canvas</td><td>11:59 pm on the last day of finals week</td></tr><tr><td><strong>The final paper</strong> (4–6 pages, ACM format, with the artifact link)</td><td>CS [5xxx]</td><td>Canvas</td><td>11:59 pm on the last day of finals week</td></tr></tbody></table><p>The report must match the tagged commit: every number reproducible from <code>final</code> with your one documented command (<a href="./../../project/milestones.html#the-final-report">the final report</a>). No grace token applies to the Final or the defense; CS [5xxx] students may use one on the final paper, but nothing moves past the University&#39;s grade deadline (<a href="./../../assessment/#late-work-and-grace-tokens">late work</a>).</p><p><strong>If you miss the defense</strong> for a reason Regulation M-1 or M-3 recognizes (official university activities, illness, family care, other compelling circumstances, religious observance), your team demos without you and your questions are rescheduled before the grade deadline. Otherwise your individual part scores 0, and since the defense is required for a C or higher, contact the instructor at once (<a href="./../../project/final-defense.html#if-you-miss-the-defense">details</a>).</p><h2 id="reading" tabindex="-1">Reading <a class="header-anchor" href="#reading" aria-label="Permalink to &quot;Reading&quot;">​</a></h2><p>None. Reread your own work instead: your PRs, your reviews, your <code>AI_LOG.md</code> entries, and your team&#39;s report.</p><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><ul><li><strong>What counts.</strong> &quot;Feature count, repository size, token spend, prompt volume, and visual polish do not substitute for demonstrated behavior, reproducible checks, controlled engineering decisions, or honest limitations.&quot; That&#39;s UT Austin CS 378&#39;s rule for its final projects, and this course&#39;s (<a href="./../../project/final-defense.html#the-principle">the principle</a>).</li><li><strong>Why the questions are individual.</strong> A team demo can&#39;t show who understands what, and students who build with agents can finish faster while understanding less of their own code (<a href="https://arxiv.org/abs/2607.26375" target="_blank" rel="noreferrer">Balepur et al.</a>).</li><li><strong>&quot;I don&#39;t know, but I&#39;d check the test for that path&quot; is a real answer,</strong> and earns credit where it belongs. Accents, grammar and nerves are never scored.</li><li><strong>The record must agree with you.</strong> Answers about AI use are compared with <code>AI_LOG.md</code> and your <code>Assisted-by:</code> trailers; a specific thing an agent got wrong, and how you caught it, is the strongest answer.</li><li><strong>Nothing upstream affects your grade.</strong> An upstream merge earns a small bonus; an open or closed upstream PR costs nothing (<a href="./../../project/contribution-rules.html#how-upstream-work-is-graded">contribution rules</a>).</li></ul><h2 id="check-your-understanding" tabindex="-1">Check your understanding <a class="header-anchor" href="#check-your-understanding" aria-label="Permalink to &quot;Check your understanding&quot;">​</a></h2><p>Practice with a teammate before the slot:</p><ol><li>Walk through your main PR in two minutes: before, after, and the test that shows the difference.</li><li>For one decision in your report: what did you specify, what did you delegate, how did you verify it, and would you delegate it again?</li><li>Pick a function you changed. If its caller upstream changed its arguments, what breaks, and which test tells you?</li><li>Name one thing an agent got wrong in your part of the work. Where is it in your <code>AI_LOG.md</code>?</li><li>Which number in your report do you trust least, and why?</li></ol><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><ul><li><strong>Your Codespace won&#39;t start:</strong> use a teammate&#39;s on the same tag, or a local clone in a dev container; that&#39;s why you start 30 minutes early.</li><li><strong>The network fails mid-demo:</strong> show the CI run on the <code>final</code> tag or your screenshots, and say why; a fallback with a reason still earns credit.</li><li><strong>The check runs long:</strong> start it first; if it isn&#39;t done by minute 5, open its CI run on the tagged commit.</li><li><strong>Canvas is down at the deadline:</strong> keep the file with its timestamp, tell the instructor at once, and submit when Canvas is back.</li></ul><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li>Keep following any upstream PR you opened: answer review, or close it politely with a note (<a href="./../../project/contribution-rules.html#optional-upstream-prs-tier-3">contribution rules</a>).</li><li>Revoke the keys and tokens you made for the course at each provider, and stop or delete unused Codespaces (<a href="./../../setup/api-keys.html">API keys and tokens</a>).</li><li>The <a href="./../../resources/reading-list.html">reading list</a> and <a href="./../../resources/case-studies.html">case studies</a> stay online.</li></ul>',32)])])}const g=t(n,[["render",s]]);export{f as __pageData,g as default};
